import React, { useEffect, useState } from 'react';
import { Outlet, useLocation } from 'react-router-dom';
import Navigation from './Navigation';
import Footer from './Footer';

function Layout({ mode, modeChange }: { mode: string; modeChange: () => void }) {
  const location = useLocation();
  const [isLoaded, setIsLoaded] = useState(false);

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    setIsLoaded(false);
    const timeout = window.setTimeout(() => setIsLoaded(true), 20);
    return () => window.clearTimeout(timeout);
  }, [location.pathname]);

  return (
    <div className={`main-container ${mode === 'dark' ? 'dark-mode' : 'light-mode'}`}>
      <Navigation parentToChild={{ mode }} modeChange={modeChange} />
      <main className={`route-wrapper${isLoaded ? ' active' : ''}`}>
        <Outlet />
      </main>
      <Footer />
    </div>
  );
}

export default Layout;
